  // ---- calculator ----
  'calc.h1': ['Premium calculator', '保费计算器', 'Kalkulator premium', 'பிரீமியம் கணிப்பான்'],
  'calc.sub': ['Move the sliders to see how your daily habits change your yearly premium. Same formula the policy uses.', '拖动滑块，查看日常习惯如何影响年保费。与保单使用的公式完全一致。', 'Gerakkan peluncur untuk lihat bagaimana tabiat harian mengubah premium tahunan. Formula sama digunakan oleh polisi.', 'ஸ்லைடர்களை நகர்த்தி, உங்கள் தினசரிப் பழக்கங்கள் ஆண்டு பிரீமியத்தை எப்படி மாற்றுகின்றன என்று பாருங்கள். பாலிசி பயன்படுத்தும் அதே சூத்திரம்.'],
  'calc.steps': ['Average daily steps', '每日平均步数', 'Purata langkah harian', 'சராசரி தினசரி படிகள்'],
  'calc.exercise': ['Exercise per week (minutes)', '每周运动时间（分钟）', 'Senaman seminggu (minit)', 'வாரத்திற்கு உடற்பயிற்சி (நிமிடங்கள்)'],
  'calc.sleep': ['Average sleep (hours per night)', '平均睡眠（每晚小时）', 'Purata tidur (jam semalam)', 'சராசரி தூக்கம் (இரவுக்கு மணி)'],
  'calc.hr': ['Resting heart rate (bpm)', '静息心率（次/分）', 'Kadar denyutan jantung rehat (bpm)', 'ஓய்வு இதயத் துடிப்பு (bpm)'],
  'calc.sub.opt': ['Add the premium app (RM5/month: deep insights & coaching)', '添加高级应用（RM5/月：深度分析与指导）', 'Tambah apl premium (RM5/bulan: pandangan mendalam & bimbingan)', 'பிரீமியம் ஆப் சேர்க்கவும் (RM5/மாதம்: ஆழமான நுண்ணறிவு & பயிற்சி)'],
  'calc.score': ['Your health score', '你的健康分数', 'Skor kesihatan anda', 'உங்கள் ஆரோக்கிய மதிப்பெண்'],
  'calc.base': ['Base premium', '基础保费', 'Premium asas', 'அடிப்படை பிரீமியம்'],
  'calc.adj': ['Wearable adjustment', '可穿戴设备调整', 'Pelarasan peranti', 'சாதன சரிசெய்தல்'],
  'calc.yours': ['Your annual premium', '你的年保费', 'Premium tahunan anda', 'உங்கள் ஆண்டு பிரீமியம்'],
  'calc.permonth': ['Approximately per month', '约每月', 'lebih kurang sebulan', 'மாதத்திற்கு சுமார்'],
  'calc.saved': ['You save vs the flat base', '相比固定基础保费节省', 'Anda jimat berbanding asas rata', 'சீரான அடிப்படையுடன் ஒப்பிடும்போது சேமிப்பு'],
  'calc.extra': ['More than the flat base', '高于固定基础保费', 'Lebih daripada asas rata', 'சீரான அடிப்படையை விட அதிகம்'],
  'calc.breakdown': ['Score breakdown', '分数构成', 'Pecahan skor', 'மதிப்பெண் பிரிப்பு'],
  'calc.formula.h': ['The exact formula', '精确公式', 'Formula sebenar', 'துல்லியமான சூத்திரம்'],
  'calc.formula.p': ['Score = 35% steps + 30% exercise + 20% sleep + 15% heart rate. A score of 50 means no change. 100 means −15%, 0 means +15%. Premium = RM600 × (1 + adjustment).', '分数 = 35% 步数 + 30% 运动 + 20% 睡眠 + 15% 心率。50 分代表不变，100 分为 −15%，0 分为 +15%。保费 = RM600 x（1 + 调整幅度）。', 'Skor = 35% langkah + 30% senaman + 20% tidur + 15% kadar jantung. Skor 50 bermaksud tiada perubahan. 100 ialah −15%, 0 ialah +15%. Premium = RM600 x (1 + pelarasan).', 'மதிப்பெண் = 35% படிகள் + 30% உடற்பயிற்சி + 20% தூக்கம் + 15% இதயத் துடிப்பு. 50 என்றால் மாற்றம் இல்லை; 100 என்றால் −15%, 0 என்றால் +15%. பிரீமியம் = RM600 x (1 + சரிசெய்தல்).'],
  'calc.cta': ['Apply with these numbers', '以此数据投保', 'Mohon dengan angka ini', 'இந்த எண்களுடன் விண்ணப்பிக்கவும்'],
  'calc.note': ['Indicative only. The final premium at renewal uses your 12-month average from your linked device.', '仅供参考。续保时的最终保费以你已连接设备的 12 个月平均值为准。', 'Hanya sebagai panduan. Premium akhir semasa pembaharuan menggunakan purata 12 bulan daripada peranti anda.', 'குறிப்புக்கு மட்டும். புதுப்பிப்பின் இறுதி பிரீமியம் உங்கள் இணைக்கப்பட்ட சாதனத்தின் 12 மாத சராசரியைப் பயன்படுத்தும்.'],
  'comp.steps': ['Steps', '步数', 'Langkah', 'படிகள்'],
  'comp.exercise': ['Exercise', '运动', 'Senaman', 'உடற்பயிற்சி'],
  'comp.sleep': ['Sleep', '睡眠', 'Tidur', 'தூக்கம்'],
